CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('administrador','vendedor','cliente') NOT NULL DEFAULT 'vendedor',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS terminals(id INT AUTO_INCREMENT PRIMARY KEY,city VARCHAR(100) NOT NULL,name VARCHAR(140) NOT NULL,address VARCHAR(255) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS buses(id INT AUTO_INCREMENT PRIMARY KEY,plate VARCHAR(12) NOT NULL UNIQUE,bus_type VARCHAR(50) NOT NULL,deck_count TINYINT NOT NULL,capacity SMALLINT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS bus_seats(id INT AUTO_INCREMENT PRIMARY KEY,bus_id INT NOT NULL,deck_level TINYINT NOT NULL,position_row TINYINT NOT NULL,position_col TINYINT NOT NULL,label VARCHAR(8) NOT NULL,seat_type ENUM('normal','semicama','cama') NOT NULL,UNIQUE(bus_id,deck_level,label),FOREIGN KEY(bus_id) REFERENCES buses(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS routes(id INT AUTO_INCREMENT PRIMARY KEY,origin_id INT NOT NULL,destination_id INT NOT NULL,duration_minutes SMALLINT NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(origin_id) REFERENCES terminals(id),FOREIGN KEY(destination_id) REFERENCES terminals(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS route_stops(route_id INT NOT NULL,terminal_id INT NOT NULL,stop_order TINYINT NOT NULL,PRIMARY KEY(route_id,stop_order),FOREIGN KEY(route_id) REFERENCES routes(id),FOREIGN KEY(terminal_id) REFERENCES terminals(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS route_fares(route_id INT NOT NULL,seat_type ENUM('normal','semicama','cama') NOT NULL,price DECIMAL(9,2) NOT NULL,PRIMARY KEY(route_id,seat_type),FOREIGN KEY(route_id) REFERENCES routes(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trips(id INT AUTO_INCREMENT PRIMARY KEY,route_id INT NOT NULL,bus_id INT NOT NULL,departure_at DATETIME NOT NULL,status ENUM('programado','en curso','finalizado','cancelado') NOT NULL DEFAULT 'programado',FOREIGN KEY(route_id) REFERENCES routes(id),FOREIGN KEY(bus_id) REFERENCES buses(id),INDEX(departure_at,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trip_drivers(trip_id INT NOT NULL,driver_name VARCHAR(120) NOT NULL,PRIMARY KEY(trip_id,driver_name),FOREIGN KEY(trip_id) REFERENCES trips(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS passengers(id INT AUTO_INCREMENT PRIMARY KEY,dni CHAR(8) NOT NULL UNIQUE,full_name VARCHAR(160) NOT NULL,age TINYINT UNSIGNED NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trip_seats(id INT AUTO_INCREMENT PRIMARY KEY,trip_id INT NOT NULL,bus_seat_id INT NOT NULL,label VARCHAR(8) NOT NULL,deck_level TINYINT NOT NULL,position_row TINYINT NOT NULL,position_col TINYINT NOT NULL,seat_type ENUM('normal','semicama','cama') NOT NULL,price DECIMAL(9,2) NOT NULL,status ENUM('available','held','sold') NOT NULL DEFAULT 'available',hold_token CHAR(32) NULL,hold_until DATETIME NULL,UNIQUE(trip_id,bus_seat_id),INDEX(trip_id,status,hold_until),FOREIGN KEY(trip_id) REFERENCES trips(id),FOREIGN KEY(bus_seat_id) REFERENCES bus_seats(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tickets(id BIGINT AUTO_INCREMENT PRIMARY KEY,trip_id INT NOT NULL,trip_seat_id INT NOT NULL UNIQUE,passenger_id INT NOT NULL,price DECIMAL(9,2) NOT NULL,status ENUM('valid','boarded','cancelled','changed') NOT NULL DEFAULT 'valid',qr_code CHAR(32) NOT NULL UNIQUE,sold_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(trip_id) REFERENCES trips(id),FOREIGN KEY(trip_seat_id) REFERENCES trip_seats(id),FOREIGN KEY(passenger_id) REFERENCES passengers(id),FOREIGN KEY(sold_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments(id BIGINT AUTO_INCREMENT PRIMARY KEY,ticket_id BIGINT NOT NULL UNIQUE,method ENUM('cash','card','transfer') NOT NULL,amount DECIMAL(9,2) NOT NULL,status ENUM('paid','refunded') NOT NULL DEFAULT 'paid',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(ticket_id) REFERENCES tickets(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS post_sale_policies(id INT AUTO_INCREMENT PRIMARY KEY,action ENUM('cancellation','change') NOT NULL,penalty_percent DECIMAL(5,2) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS boarding_events(id BIGINT AUTO_INCREMENT PRIMARY KEY,ticket_id BIGINT NOT NULL UNIQUE,boarded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(ticket_id) REFERENCES tickets(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS demo_records(id BIGINT AUTO_INCREMENT PRIMARY KEY,passenger_name VARCHAR(140) NOT NULL,dni CHAR(8) NOT NULL,origin VARCHAR(80) NOT NULL,destination VARCHAR(80) NOT NULL,departure_at DATETIME NOT NULL,seat_label VARCHAR(8) NOT NULL,amount DECIMAL(8,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
