INSERT IGNORE INTO bus_seats(bus_id,deck_level,position_row,position_col,label,seat_type)
SELECT b.id,d.level_no,r.row_no,c.col_no,CONCAT(CHAR(64+r.row_no),c.col_no),CASE WHEN b.id=1 THEN 'cama' WHEN b.id=2 THEN 'semicama' WHEN d.level_no=2 THEN 'cama' ELSE 'semicama' END
FROM buses b JOIN (SELECT 1 level_no UNION SELECT 2) d ON d.level_no<=b.deck_count JOIN (SELECT 1 row_no UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10) r ON r.row_no<=b.capacity/(b.deck_count*2) JOIN (SELECT 1 col_no UNION SELECT 2) c;
