INSERT IGNORE INTO trip_drivers(trip_id,driver_name) SELECT id,CONCAT('Conductor de prueba ',id) FROM trips;
INSERT IGNORE INTO trip_seats(trip_id,bus_seat_id,label,deck_level,position_row,position_col,seat_type,price)
SELECT t.id,bs.id,bs.label,bs.deck_level,bs.position_row,bs.position_col,bs.seat_type,rf.price FROM trips t JOIN bus_seats bs ON bs.bus_id=t.bus_id JOIN route_fares rf ON rf.route_id=t.route_id AND rf.seat_type=bs.seat_type;
INSERT INTO post_sale_policies(action,penalty_percent) SELECT 'cancellation',15 WHERE NOT EXISTS(SELECT 1 FROM post_sale_policies WHERE action='cancellation');
INSERT INTO post_sale_policies(action,penalty_percent) SELECT 'change',10 WHERE NOT EXISTS(SELECT 1 FROM post_sale_policies WHERE action='change');

